    const params = { Bucket, Key };

    try {
        const headObjectCommand = new HeadObjectCommand(params);
        await s3Client.send(headObjectCommand);
        return true;
    } catch (err) {
        if (err.name === 'NotFound') {
            return false;
        } else {
            throw err;
        }
    }
};

