     */
    static dimensionPrice(consumptionPrice?: string): number {
        const price = parseFloat(consumptionPrice);
        return Number.isFinite(price) ? price : 0;
    }

    /**
     * How much of a dimension's usage the plan permits charging for over the invoiced
     * period. Usage is chargeable only once it passes a finite allowance the plan lets
     * the customer exceed, so an unlimited allowance, an allowance the usage never
     * exhausted, or a plan which forbids overage leave nothing to charge for.
     */
    static billableUsageBeyondEntitlement({
        total,
        usageEntitlement,
        overageAllowed,
    }: {
        total: number;
        usageEntitlement?: number | 'inf';
        overageAllowed?: overageAllowedEnum;
    }): number {
        if (usageEntitlement === undefined || usageEntitlement === null) {
            return total;
        }
        if (overageAllowed !== overageAllowedEnum.true) {
            return 0;
        }
        if (usageEntitlement === 'inf') {
            return 0;
