cat <<'EOF' > src/offering/entities/offeringEntitlement.entity.spec.ts
import { Offering } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';
import { InvoiceLineItems } from '../../invoice/entities/invoice.entity.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import {
    aggregationInterval,
    aggregationMethod,
    overageAllowedEnum,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';

const businessID = 'biz-test';
const customerId = 'cus-test';
const startDate = new Date('2026-07-01T00:00:00Z');
const endDate = new Date('2026-08-01T00:00:00Z');

const dimension = (overrides: Record<string, any> = {}) => ({
    aggregationInterval: aggregationInterval.hour,
    aggregationMethod: aggregationMethod.sum,
    dimensionId: 'dim',
    dimensionName: 'Dimension',
    rounding: roundingEnum.round,
    usageIncrement: '1',
    consumptionUnit: { unit: 'count-based', type: 'count' },
    ...overrides,
});

const gatherLines = async ({
    dimensions,
    usage,
    settings,
}: {
    dimensions: Array<Record<string, any>>;
    usage: Record<string, string>;
    settings?: ReadSettingsResponseData;
}) => {
    const offeringConfig = {
        offeringId: 'off-test',
        offeringName: 'Test Offering',
        offeringType: OfferingType.usageBased,
        billingCycle: ValidBillingCycles.monthly,
        dimensions,
    } as unknown as ReadOfferingResponseData;
    const offeringInstance = Offering.getInstance(
        offeringConfig,
        customerId,
        businessID,
        undefined,
        settings,
        undefined,
        undefined,
        undefined,
        Object.keys(usage).map((dimensionId) => ({
            dimensionId,
            offeringId: 'off-test',
            usage: [
                {
                    value: usage[dimensionId],
                    startTime: startDate.toISOString(),
                    endTime: endDate.toISOString(),
                },
            ],
        })),
    );
    const lineItems = await Offering.getLineItemsForUsage({
        startDate,
        endDate,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID,
        customerId,
        customerService: undefined,
        dimensions: offeringConfig.dimensions,
        offeringInstance,
    });
    return lineItems.getLineItems();
};

describe('Entitlements, overage and free dimensions on metered invoice lines', () => {
    test('usage beyond an exhausted allowance is the only usage charged', async () => {
        const lines = await gatherLines({
            dimensions: [
                dimension({
                    dimensionId: 'seats',
                    dimensionName: 'Seats',
                    consumptionPrice: '10.00',
                    usageEntitlement: 10,
                    overageAllowed: overageAllowedEnum.true,
                }),
            ],
            usage: { seats: '12' },
        });
        expect(lines).toEqual([expect.objectContaining({ name: 'Seats - Test Offering', quantity: 2, unitCost: 10 })]);
    });

    test('an allowance the usage has not exhausted charges nothing and carries no line', async () => {
        const lines = await gatherLines({
            dimensions: [
                dimension({
                    dimensionId: 'minutes',
                    dimensionName: 'Minutes',
                    consumptionPrice: '0.02',
                    usageEntitlement: 100,
                    overageAllowed: overageAllowedEnum.true,
                }),
            ],
            usage: { minutes: '80' },
        });
        expect(lines).toEqual([]);
    });

    test('an unlimited allowance charges nothing and carries no line', async () => {
        const lines = await gatherLines({
            dimensions: [
                dimension({
                    dimensionId: 'storage',
                    dimensionName: 'Storage',
                    consumptionPrice: '0.20',
                    usageEntitlement: 'inf',
                    overageAllowed: overageAllowedEnum.true,
                }),
            ],
            usage: { storage: '40' },
        });
        expect(lines).toEqual([]);
    });

    test('a plan which forbids overage charges nothing beyond the allowance', async () => {
        const lines = await gatherLines({
            dimensions: [
                dimension({
                    dimensionId: 'reports',
                    dimensionName: 'Reports',
                    consumptionPrice: '1.00',
                    usageEntitlement: 5,
                    overageAllowed: overageAllowedEnum.false,
                }),
                dimension({
                    dimensionId: 'tasks',
                    dimensionName: 'Tasks',
                    consumptionPrice: '0.10',
                    usageEntitlement: 50,
                }),
            ],
            usage: { reports: '7', tasks: '70' },
        });
        expect(lines).toEqual([]);
    });

    test('an allowance of zero leaves all of the usage chargeable', async () => {
        const lines = await gatherLines({
            dimensions: [
                dimension({
                    dimensionId: 'requests',
                    dimensionName: 'Requests',
                    consumptionPrice: '0.40',
                    usageEntitlement: 0,
                    overageAllowed: overageAllowedEnum.true,
                }),
            ],
            usage: { requests: '10' },
        });
        expect(lines).toEqual([
            expect.objectContaining({ name: 'Requests - Test Offering', quantity: 10, unitCost: 0.4 }),
        ]);
    });

    test('dimensions priced at zero are shown by default', async () => {
        const lines = await gatherLines({
            dimensions: [dimension({ dimensionId: 'alerts', dimensionName: 'Alerts', consumptionPrice: '0.00' })],
            usage: { alerts: '5' },
            settings: { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData,
        });
        expect(lines).toEqual([expect.objectContaining({ name: 'Alerts - Test Offering', quantity: 5, unitCost: 0 })]);
    });

    test('dimensions priced at zero are left off when the invoice settings hide them', async () => {
        const lines = await gatherLines({
            dimensions: [dimension({ dimensionId: 'alerts', dimensionName: 'Alerts', consumptionPrice: '0.00' })],
            usage: { alerts: '5' },
            settings: { freeDimensionOnInvoice: FreeDimensionOnInvoice.hide } as ReadSettingsResponseData,
        });
        expect(lines).toEqual([]);
    });

    test('a priced dimension without any usage carries no line', async () => {
        const lines = await gatherLines({
            dimensions: [dimension({ dimensionId: 'scans', dimensionName: 'Scans', consumptionPrice: '0.50' })],
            usage: { scans: '0' },
        });
        expect(lines).toEqual([]);
    });
});
EOF
